"""Pages of parcels."""


def page_count(n_items, page_size):
    """Return how many pages are needed to show n_items, page_size to a page."""
    return n_items // page_size


def page(parcels, number, page_size):
    """Return page `number` of parcels. Pages are numbered from 1."""
    start = (number - 1) * page_size
    return parcels[start:start + page_size]


def all_pages(parcels, page_size):
    """Return every page of parcels, in order."""
    return [page(parcels, n, page_size) for n in range(1, page_count(len(parcels), page_size) + 1)]


def depot_names(parcels):
    """Return the distinct depot values, in first-seen order."""
    names = []
    for x in parcels:
        if x.depot not in names:
            names.append(x.depot)
    return names


def describe_parcel(parcel):
    """Return a one-line description of a parcel."""
    return "%s: %s" % (parcel.depot, parcel.grams)

